/**
 * "Blocked by" links between issues of one organization. A link is a directed edge `issue → blocker`; the graph must stay acyclic.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, inArray, isNull, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

/** What `insertDependency` did; `cycle` means nothing was written. */
export type InsertDependencyResult =
  | {
      readonly outcome: "created" | "exists";
      readonly dependency: IssueDependency;
    }
  | { readonly outcome: "cycle" };

function selectDependency(orgId: OrgId, issueId: IssueId, blockerId: IssueId) {
  return getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
}

/**
 * True when `target` can be reached from `from` by following "blocked by"
 * links, i.e. `from` is (transitively) blocked by `target`. Archived issues
 * keep their links, so they stay on the path.
 */
function isTransitivelyBlockedBy(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): boolean {
  const seen = new Set<string>([from]);
  let frontier: string[] = [from];

  while (frontier.length > 0) {
    const rows = getDb()
      .select({ blockerId: issueDependencies.blockerId })
      .from(issueDependencies)
      .where(
        and(
          orgPredicate(issueDependencies.orgId, orgId),
          inArray(issueDependencies.issueId, frontier),
        ),
      )
      .all();

    const next: string[] = [];
    for (const { blockerId } of rows) {
      if (blockerId === target) return true;
      if (seen.has(blockerId)) continue;
      seen.add(blockerId);
      next.push(blockerId);
    }
    frontier = next;
  }

  return false;
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = selectDependency(orgId, issueId, blockerId);
  return row ? toIssueDependency(row) : null;
}

/**
 * Stores `issueId` blocked by `blockerId` unless the link already exists
 * (returned as-is) or would close a loop. The existence check, the cycle check
 * and the insert run without yielding, so two concurrent calls cannot each
 * pass the check and then together create a cycle.
 */
export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<InsertDependencyResult> {
  const existing = selectDependency(orgId, issueId, blockerId);
  if (existing) {
    return { outcome: "exists", dependency: toIssueDependency(existing) };
  }

  if (
    issueId === blockerId ||
    isTransitivelyBlockedBy(orgId, blockerId, issueId)
  ) {
    return { outcome: "cycle" };
  }

  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();

  return { outcome: "created", dependency: toIssueDependency(row) };
}

/** Resolves `true` when a link was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();

  return rows.length > 0;
}

/** Live (non-archived) blockers of an issue, open or closed, by issue number. */
export async function listBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          orgPredicate(issues.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map(({ issue }) => issue.id as IssueId),
  );

  return rows.map(({ issue }) =>
    toIssue(issue, (labels[issue.id] ?? []).map((label) => label.id)),
  );
}

