/**
 * Issue dependencies ("blocked by" links): who may record them, which links are refused, and the error that guards completion of a blocked issue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived
 */
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Raised when an issue is moved to `done` while blockers are still open.
 * `blockerIds` names exactly those open blockers, by issue number.
 */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(
      `Issue ${issueId} cannot be completed: ${blockerIds.length} open blocker(s)`,
    );
    this.name = "IssueBlockedError";
  }
}

interface DependencyInput {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
}

/**
 * Records "`issueId` is blocked by `blockerId`". Recording is an edit of the
 * blocked issue, so it needs `issue:update` on that issue. A link that already
 * exists is returned unchanged; one that would close a loop is refused.
 */
export async function addBlocker(
  actor: Actor,
  input: DependencyInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }

  const result = await dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
  if (result.outcome === "cycle") {
    throw new Error(
      `Issue ${blocker.id} is already blocked by issue ${issue.id}, directly or through other issues`,
    );
  }

  return result.dependency;
}

/** Resolves `true` when a link was removed, `false` when there was none. */
export async function removeBlocker(
  actor: Actor,
  input: DependencyInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** The issue's blockers that are not archived, open or closed, by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockers(orgId, issueId);
}

