/**
 * Tells an assignee when the last open blocker of their issue closes. Reacts to the events that can close a blocker; nothing here is called by the issue service itself.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { isArchived } from "@/lib/soft-delete";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * Notifies the assignee of every issue that `closedBlockerIds` were holding
 * back and that no open blocker holds back any longer. The blocked issue must
 * itself still be live and open, and have an assignee.
 */
async function notifyUnblocked(
  orgId: OrgId,
  actorId: UserId | null,
  closedBlockerIds: readonly IssueId[],
): Promise<void> {
  const blocked = await dependencyRepo.listBlockedIssues(orgId, closedBlockerIds);

  for (const issue of blocked) {
    if (issue.assigneeId === null || isClosedStatus(issue.status)) continue;

    const stillOpen = await dependencyRepo.listOpenBlockerIds(orgId, issue.id);
    if (stillOpen.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue you are assigned to is unblocked",
      body: `Issue ${issue.id} has no open blockers left`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

/**
 * A blocker closes when it moves into `done`/`canceled` from an open status, or
 * when it is archived while still open — including through a project cascade.
 * Closed → closed changes never qualify, and a reopened blocker that closes
 * again qualifies again because each close is its own event.
 */
export function registerUnblockListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.actorId, [payload.issueId]);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      // Archiving leaves the status alone, so the stored one is the one it had.
      if (!issue || !isArchived(issue) || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.actorId, [issue.id]);
    }),
    subscribe("project.archived", async (payload) => {
      const archivedOpen = payload.archivedOpenIssueIds ?? [];
      if (archivedOpen.length === 0) return;
      await notifyUnblocked(payload.orgId, payload.actorId, archivedOpen);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

