/**
 * Issue dependencies: link rules, the completion gate and the unblocked notification.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { onHandlerError, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { notificationKindSchema, updateNotificationPreferenceSchema } from "@/schemas/notification";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import {
  addBlocker,
  IssueBlockedError,
  listBlockers,
  removeBlocker,
} from "@/server/services/issue-dependency-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("deps");
  other = await createTenant("deps-other");
  registerEventHandlers();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function makeIssue(
  overrides: Parameters<typeof issueInput>[2] = {},
  t: Tenant = tenant,
) {
  return issueService.createIssue(
    t.actors.member,
    issueInput(t.org.id, t.project.id, overrides),
  );
}

function input(issueId: IssueId, blockerId: IssueId, t: Tenant = tenant) {
  return { orgId: t.org.id, issueId, blockerId };
}

async function setStatus(actor: Actor, issueId: IssueId, status: IssueStatus) {
  return issueService.changeIssueStatus(actor, {
    orgId: actor.orgId,
    issueId,
    status,
  });
}

async function unblockedFor(userId: UserId) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
  });
  return page.items;
}

describe("addBlocker", () => {
  it("records the link and attributes it to the actor", async () => {
    const blocked = await makeIssue();
    const blocker = await makeIssue();

    const link = await addBlocker(tenant.actors.member, input(blocked.id, blocker.id));

    expect(link).toMatchObject({
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
      createdBy: tenant.userIds.member,
    });
  });

  it("returns the existing link instead of storing a duplicate", async () => {
    const blocked = await makeIssue();
    const blocker = await makeIssue();

    const first = await addBlocker(tenant.actors.member, input(blocked.id, blocker.id));
    const again = await addBlocker(tenant.actors.admin, input(blocked.id, blocker.id));

    expect(again).toEqual(first);
    expect(await listBlockers(tenant.actors.member, tenant.org.id, blocked.id)).toHaveLength(1);
  });

  it("refuses an issue blocking itself", async () => {
    const issue = await makeIssue();
    await expect(
      addBlocker(tenant.actors.member, input(issue.id, issue.id)),
    ).rejects.toThrow();
    expect(await listBlockers(tenant.actors.member, tenant.org.id, issue.id)).toHaveLength(0);
  });

  it("refuses direct and transitive cycles", async () => {
    const a = await makeIssue();
    const b = await makeIssue();
    const c = await makeIssue();
    const d = await makeIssue();

    await addBlocker(tenant.actors.member, input(a.id, b.id));
    await addBlocker(tenant.actors.member, input(b.id, c.id));
    await addBlocker(tenant.actors.member, input(c.id, d.id));

    await expect(addBlocker(tenant.actors.member, input(b.id, a.id))).rejects.toThrow();
    await expect(addBlocker(tenant.actors.member, input(d.id, a.id))).rejects.toThrow();
    await expect(addBlocker(tenant.actors.member, input(c.id, a.id))).rejects.toThrow();

    // A diamond is not a cycle.
    await expect(addBlocker(tenant.actors.member, input(a.id, d.id))).resolves.toBeDefined();
    expect(await listBlockers(tenant.actors.member, tenant.org.id, d.id)).toHaveLength(0);
  });

  it("cannot create a cycle through two concurrent calls", async () => {
    const a = await makeIssue();
    const b = await makeIssue();

    const results = await Promise.allSettled([
      addBlocker(tenant.actors.member, input(a.id, b.id)),
      addBlocker(tenant.actors.member, input(b.id, a.id)),
    ]);

    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
  });

  it("rejects an archived issue on either side", async () => {
    const live = await makeIssue();
    const archived = await makeIssue();
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    await expect(
      addBlocker(tenant.actors.member, input(live.id, archived.id)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      addBlocker(tenant.actors.member, input(archived.id, live.id)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("enforces tenant scope, existence and the edit permission", async () => {
    const blocked = await makeIssue();
    const blocker = await makeIssue();
    const foreign = await makeIssue({}, other);

    await expect(
      addBlocker(tenant.actors.member, input(blocked.id, blocker.id, other)),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      addBlocker(tenant.actors.member, input(blocked.id, foreign.id)),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      addBlocker(tenant.actors.member, input(foreign.id, blocker.id)),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      addBlocker(tenant.actors.viewer, input(blocked.id, blocker.id)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id)).toHaveLength(0);
  });
});

describe("removeBlocker", () => {
  it("reports whether a link was removed", async () => {
    const blocked = await makeIssue();
    const blocker = await makeIssue();
    await addBlocker(tenant.actors.member, input(blocked.id, blocker.id));

    expect(await removeBlocker(tenant.actors.member, input(blocked.id, blocker.id))).toBe(true);
    expect(await removeBlocker(tenant.actors.member, input(blocked.id, blocker.id))).toBe(false);
  });

  it("only needs the blocked issue to exist, and the edit permission", async () => {
    const blocked = await makeIssue();
    const ghost = "01ARZ3NDEKTSV4RRFFQ69G5FAV" as IssueId;

    expect(await removeBlocker(tenant.actors.member, input(blocked.id, ghost))).toBe(false);
    await expect(
      removeBlocker(tenant.actors.member, input(ghost, blocked.id)),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      removeBlocker(tenant.actors.viewer, input(blocked.id, ghost)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      removeBlocker(tenant.actors.member, input(blocked.id, ghost, other)),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("does not notify", async () => {
    const assignee = tenant.userIds.admin;
    const blocked = await makeIssue({ assigneeId: assignee });
    const blocker = await makeIssue();
    await addBlocker(tenant.actors.member, input(blocked.id, blocker.id));

    await removeBlocker(tenant.actors.member, input(blocked.id, blocker.id));

    expect((await unblockedFor(assignee)).filter((n) => n.href === `/issues/${blocked.id}`)).toEqual([]);
  });
});

describe("listBlockers", () => {
  it("returns live blockers, open or closed, ordered by number", async () => {
    const blocked = await makeIssue();
    const first = await makeIssue();
    const second = await makeIssue();
    const third = await makeIssue();
    const gone = await makeIssue();

    for (const blocker of [third, gone, first, second]) {
      await addBlocker(tenant.actors.member, input(blocked.id, blocker.id));
    }
    await setStatus(tenant.actors.member, second.id, "canceled");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);

    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);

    expect(listed.map((issue) => issue.id)).toEqual([first.id, second.id, third.id]);
  });

  it("enforces tenant scope and existence", async () => {
    const issue = await makeIssue();
    const foreign = await makeIssue({}, other);

    await expect(
      listBlockers(tenant.actors.member, other.org.id, foreign.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      listBlockers(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(listBlockers(tenant.actors.viewer, tenant.org.id, issue.id)).resolves.toEqual([]);
  });
});

describe("completion gate", () => {
  it("blocks done while a blocker is open and names exactly the open ones", async () => {
    const blocked = await makeIssue();
    const open = await makeIssue();
    const done = await makeIssue();
    const archived = await makeIssue();
    await addBlocker(tenant.actors.member, input(blocked.id, open.id));
    await addBlocker(tenant.actors.member, input(blocked.id, done.id));
    await addBlocker(tenant.actors.member, input(blocked.id, archived.id));
    await setStatus(tenant.actors.member, done.id, "done");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const events = capture("issue.status_changed");
    const error = await setStatus(tenant.actors.member, blocked.id, "done").catch(
      (thrown: unknown) => thrown,
    );

    expect(error).toBeInstanceOf(IssueBlockedError);
    expect((error as IssueBlockedError).code).toBe("conflict");
    expect((error as IssueBlockedError).blockerIds).toEqual([open.id]);
    expect(events).toHaveLength(0);
    expect((await issueService.getIssue(tenant.actors.member, tenant.org.id, blocked.id)).issue.status).toBe("backlog");
  });

  it("also guards the board move, and leaves other statuses free", async () => {
    const blocked = await makeIssue();
    const blocker = await makeIssue();
    await addBlocker(tenant.actors.member, input(blocked.id, blocker.id));

